def count_semiprimes_in_range(a, b):
    def prime_factor_count(x):
        n = x
        factors = 0
        d = 2
        while d * d <= n:
            while n % d == 0:
                n //= d
                factors += 1
                if factors > 2:
                    return factors
            d += 1
        if n > 1:
            factors += 1
        return factors
    return sum(1 for x in range(a, b + 1) if prime_factor_count(x) == 2)

