def first_and_last_weekday_of_month(year, month, weekday_num):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def weekday_of(y, m, d):
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        yy = y - 1 if m < 3 else y
        w = (yy + yy // 4 - yy // 100 + yy // 400 + t[m - 1] + d) % 7
        return (w + 6) % 7
    days_in_month = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    dim = days_in_month[month - 1]
    first_wd = weekday_of(year, month, 1)
    first_day = 1 + (weekday_num - first_wd) % 7
    last_wd = weekday_of(year, month, dim)
    last_day = dim - (last_wd - weekday_num) % 7
    return (first_day, last_day)

