def days_to_end_of_year(y, m, d):
    def leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    month_lengths = [31, 29 if leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    day_of_year = sum(month_lengths[:m - 1]) + d
    year_total = 366 if leap(y) else 365
    return year_total - day_of_year

def justify_line(words, width):
    if len(words) == 1:
        return words[0] + ' ' * (width - len(words[0]))
    total_len = sum(len(w) for w in words)
    total_gap_spaces = width - total_len
    num_gaps = len(words) - 1
    min_spaces = total_gap_spaces // num_gaps
    extra = total_gap_spaces % num_gaps
    pieces = []
    for i in range(num_gaps):
        pieces.append(words[i])
        spaces = min_spaces + (1 if i < extra else 0)
        pieces.append(' ' * spaces)
    pieces.append(words[-1])
    return ''.join(pieces)

