def max_sum_subarray_of_size_k(lst, k):
    current = sum(lst[:k])
    best = current
    for i in range(k, len(lst)):
        current = current + lst[i] - lst[i - k]
        if current > best:
            best = current
    return best

def is_valid_percentage_string(s):
    if not s.endswith('%') or len(s) < 2:
        return False
    num_part = s[:-1]
    if num_part.count('.') > 1:
        return False
    if num_part.startswith('.') or num_part.endswith('.'):
        return False
    if not all(c.isdigit() or c == '.' for c in num_part):
        return False
    try:
        value = float(num_part)
    except ValueError:
        return False
    return 0 <= value <= 100

